// Extraer datos de la solicitud enviada por Diata
const body = $input.item.json.body || $input.item.json;
const recipes = body.recipes || [];
const lockedMeals = body.locked_meals || [];
const familyRules = body.family_rules || '';
const customPrompt = body.prompt || '';

// Prompt optimizado de alta precisión para Google Gemini
const systemPrompt = `Eres el Nutricionista y Chef IA Experto para la aplicación Diata.
Tu misión es planificar el menú semanal completo (de Lunes a Domingo, 7 almuerzos/comidas y 7 cenas = 14 momentos en total).

REGLAS DE OBLIGADO CUMPLIMIENTO:
1. DEBES seleccionar ÚNICAMENTE recetas existentes en el catálogo adjunto. NO inventes ningún plato.
2. CERO REPETICIÓN SEMANAL: Ninguna receta se puede repetir durante la semana. Cada una de las 14 comidas/cenas debe ser una receta distinta.
3. VARIETAD DIARIA Y CERO SOLAPAMIENTO DE INGREDIENTES: Queda TOTALMENTE PROHIBIDO repetir ingredientes principales (ej: gambas, marisco, salmón, pollo, arroz) entre la comida (☀️) y la cena (🌙) del MISMO día. Si el almuerzo lleva Gambas, la cena DEBE ser de carne, verduras o huevo pero NUNCA con Gambas.
4. RESPETA PLANES BLOQUEADOS: Si un día ya tiene un plato fijado por el usuario, mantén ese título exacto.
5. COMIDA (☀️) vs CENA (🌙): Selecciona comidas nutricionalmente contundentes para los almuerzos y opciones más ligeras para las cenas.
6. NORMAS DE LA FAMILIA: Cumple estrictamente estas costumbres: "${familyRules || 'Menú variado, equilibrado y saludable'}".
${customPrompt ? 'INSTRUCCIÓN ADICIONAL DEL USUARIO: "' + customPrompt + '"' : ''}

CATÁLOGO OFICIAL DE RECETAS PERMITIDAS:
${JSON.stringify(recipes, null, 2)}

ESTADO ACTUAL DEL PLAN Y BLOQUEOS:
${JSON.stringify(lockedMeals, null, 2)}

FORMATO OBLIGATORIO DE RESPUESTA:
Debes responder ÚNICAMENTE con un objeto JSON válido con la siguiente estructura exacta sin texto explicativo extra:
{
  "generated_menu": [
    {
      "day_index": 1,
      "day_name": "Lunes",
      "lunch": { "recipe_id": "id_receta", "title": "Título Exacto", "completed": false, "locked": false },
      "dinner": { "recipe_id": "id_receta", "title": "Título Exacto", "completed": false, "locked": false }
    }
    ... hasta el día 7 (Domingo)
  ]
}`;

return {
  json: {
    systemPrompt,
    recipes,
    lockedMeals,
    familyRules
  }
};

// Procesar e higienizar la respuesta JSON de Gemini AI
const geminiRawResponse = $input.item.json;
let parsedOutput = null;

try {
  const textContent = geminiRawResponse.candidates[0].content.parts[0].text;
  parsedOutput = JSON.parse(textContent);
} catch (e) {
  console.error('Error parseando JSON de Gemini:', e);
}

const recipes = $node["Preparar Prompt Nutricional para Gemini"].json.recipes;
const recipeMapById = new Map(recipes.map(r => [r.id, r]));
const recipeMapByTitle = new Map(recipes.map(r => [r.title.toLowerCase().trim(), r]));

// Filtro de seguridad anti-alucinaciones
let finalMenu = [];
if (parsedOutput && parsedOutput.generated_menu && Array.isArray(parsedOutput.generated_menu)) {
  finalMenu = parsedOutput.generated_menu.map(day => {
    const sanitizeMeal = (meal) => {
      if (!meal) return { recipe_id: null, title: 'Sin planificar', completed: false, locked: false };
      if (meal.locked) return meal;

      if (meal.recipe_id && recipeMapById.has(meal.recipe_id)) {
        const match = recipeMapById.get(meal.recipe_id);
        return { recipe_id: match.id, title: match.title, completed: false, locked: false };
      }
      if (meal.title && recipeMapByTitle.has(meal.title.toLowerCase().trim())) {
        const match = recipeMapByTitle.get(meal.title.toLowerCase().trim());
        return { recipe_id: match.id, title: match.title, completed: false, locked: false };
      }

      // Fallback seguro a una receta existente
      const fallback = recipes[Math.floor(Math.random() * recipes.length)];
      return { recipe_id: fallback ? fallback.id : null, title: fallback ? fallback.title : 'Sin planificar', completed: false, locked: false };
    };

    return {
      day_index: day.day_index,
      day_name: day.day_name,
      lunch: sanitizeMeal(day.lunch),
      dinner: sanitizeMeal(day.dinner)
    };
  });
}

return {
  json: {
    status: "success",
    engine: "google_gemini_1.5_flash",
    generated_menu: finalMenu
  }
};
